//! Responsive layout and screen builders.
//!
//! Everything is computed in *logical* pixels and multiplied by the
//! effective GUI scale ([`UiState::effective_scale`]) when commands and hit
//! regions are emitted, so the same layout code serves `640×360` through
//! `3840×2160`. Widget geometry is generated by the helpers on [`Ctx`] —
//! each one emits draw commands and the matching [`HitRegion`] together,
//! which keeps hitboxes pixel-identical to the visuals (and lets the test
//! suite assert zero overlaps across every screen).
//!
//! When a modal is open the underlying screen is still drawn, then the
//! modal is composited on top and — critically — only the modal's hit
//! regions are returned, so the dimmed screen is truly inert.

use crate::draw::{palette as pal, text_width, UiColor, UiDrawList, UiRect};
use crate::state::{
    tr, HitRegion, HudState, ModSyncChange, Screen, SettingsTab, UiLang, UiModal, UiState,
    WidgetId, FPS_CAP_STEPS,
};

/// Build the frame for the current screen: `(draw_list, hit_regions)`.
/// `width`/`height` are physical pixels.
pub fn layout_screen(state: &UiState, width: u32, height: u32) -> (UiDrawList, Vec<HitRegion>) {
    let mut list = UiDrawList::new();
    let mut regions = Vec::new();
    layout_screen_into(state, width, height, &mut list, &mut regions);
    (list, regions)
}

/// Buffer-reusing [`layout_screen`]: `out` is
/// [`UiDrawList::clear`]ed (recycling `Text` payload buffers) and
/// `regions` is cleared, then both are refilled — the caller's buffers
/// keep their heap capacity across frames.
pub fn layout_screen_into(
    state: &UiState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
    regions: &mut Vec<HitRegion>,
) {
    out.clear();
    regions.clear();
    let s = state.effective_scale(height) as i32;
    let mut ctx = Ctx {
        list: std::mem::take(out),
        regions: std::mem::take(regions),
        w: (width as i32) / s,
        h: (height as i32) / s,
        s,
        lang: state.lang(),
        state,
    };
    match state.screen {
        Screen::Title => title(&mut ctx),
        Screen::Settings(tab) => settings(&mut ctx, tab),
        Screen::Friends => friends(&mut ctx),
        Screen::ModSyncConsent => mod_sync(&mut ctx),
        Screen::InGameHud => hud(&mut ctx),
        Screen::Pause => pause(&mut ctx),
        Screen::CrashRecovery => crash(&mut ctx),
    }
    if state.modal.is_some() {
        ctx.regions.clear();
        modal(&mut ctx);
    }
    *out = ctx.list;
    *regions = ctx.regions;
}

// ---------------------------------------------------------------------------
// Layout context + widget helpers (all units logical px, scaled on emit)
// ---------------------------------------------------------------------------

struct Ctx<'a> {
    list: UiDrawList,
    regions: Vec<HitRegion>,
    w: i32,
    h: i32,
    s: i32,
    lang: UiLang,
    state: &'a UiState,
}

/// Logical-px rect shorthand for widget call sites.
const fn lr(x: i32, y: i32, w: i32, h: i32) -> UiRect {
    UiRect::new(x, y, w as u32, h as u32)
}

impl Ctx<'_> {
    /// Scale a logical rect to physical pixels.
    fn phys(&self, r: UiRect) -> UiRect {
        UiRect::new(
            r.x * self.s,
            r.y * self.s,
            (r.w as i32 * self.s) as u32,
            (r.h as i32 * self.s) as u32,
        )
    }

    fn rect(&self, x: i32, y: i32, w: i32, h: i32) -> UiRect {
        UiRect::new(
            x * self.s,
            y * self.s,
            (w * self.s) as u32,
            (h * self.s) as u32,
        )
    }

    fn fill(&mut self, x: i32, y: i32, w: i32, h: i32, color: UiColor) {
        self.list.fill_rect(self.rect(x, y, w, h), color);
    }

    fn border(&mut self, x: i32, y: i32, w: i32, h: i32, color: UiColor) {
        self.list
            .border_rect(self.rect(x, y, w, h), color, self.s.max(1) as u32);
    }

    fn text(&mut self, x: i32, y: i32, mult: u32, color: UiColor, s: &str) {
        self.list
            .text_str(x * self.s, y * self.s, mult * self.s as u32, color, s);
    }

    /// Centered text: `cx` is the logical center x.
    fn ctext(&mut self, cx: i32, y: i32, mult: u32, color: UiColor, s: &str) {
        let w = text_width(s, mult * self.s as u32) as i32;
        self.list.text_str(
            cx * self.s - w / 2,
            y * self.s,
            mult * self.s as u32,
            color,
            s,
        );
    }

    fn centered_in(&self, cx: i32, y: i32, h: i32, s: &str, mult: u32) -> (i32, i32) {
        let scale = mult * self.s as u32;
        let w = text_width(s, scale) as i32;
        // 8*scale px tall glyphs inside h logical px.
        let ty = y + (h - 8 * mult as i32) / 2;
        (cx - w / 2 / self.s, ty)
    }

    fn hovered(&self, id: WidgetId) -> bool {
        self.state.hover == Some(id) || self.state.focused() == Some(id)
    }

    /// Register `r` (logical px) as `id`'s interactive region.
    fn region(&mut self, id: WidgetId, r: UiRect) {
        self.regions.push(HitRegion::new(id, self.phys(r)));
    }

    /// A clickable button with label; `r` is in logical px.
    fn button(&mut self, id: WidgetId, r: UiRect, label: &str, enabled: bool) {
        let (x, y, w, h) = (r.x, r.y, r.w as i32, r.h as i32);
        let hot = enabled && self.hovered(id);
        let bg = if !enabled {
            pal::BUTTON_DISABLED
        } else if hot {
            pal::BUTTON_HOVER
        } else {
            pal::BUTTON
        };
        self.fill(x, y, w, h, bg);
        let edge = if hot {
            pal::BUTTON_BORDER_HOVER
        } else {
            pal::BUTTON_BORDER
        };
        self.border(x, y, w, h, edge);
        let fg = if enabled { pal::TEXT } else { pal::TEXT_DIM };
        let (tx, ty) = self.centered_in(x + w / 2, y, h, label, 1);
        self.text(tx, ty, 1, fg, label);
        if enabled {
            self.region(id, r);
        }
    }

    /// A button always enabled.
    fn btn(&mut self, id: WidgetId, r: UiRect, label: &str) {
        self.button(id, r, label, true);
    }

    /// Horizontal slider with a centered "Label: value" caption.
    fn slider(&mut self, id: WidgetId, r: UiRect, frac: f32, label: &str) {
        let (x, y, w, h) = (r.x, r.y, r.w as i32, r.h as i32);
        let hot = self.hovered(id);
        self.fill(x, y, w, h, pal::BUTTON);
        let inner = self.rect(x + 1, y + 1, w - 2, h - 2);
        self.list.progress_bar(
            inner,
            frac,
            pal::ACCENT.with_alpha(160),
            UiColor::rgba(0, 0, 0, 60),
            if hot {
                pal::BUTTON_BORDER_HOVER
            } else {
                pal::BUTTON_BORDER
            },
        );
        let (tx, ty) = self.centered_in(x + w / 2, y, h, label, 1);
        self.text(tx, ty, 1, pal::TEXT, label);
        self.region(id, r);
    }

    /// Editable text field.
    fn textfield(
        &mut self,
        id: WidgetId,
        r: UiRect,
        content: &str,
        focused: bool,
        placeholder: &str,
    ) {
        let (x, y, w, h) = (r.x, r.y, r.w as i32, r.h as i32);
        self.fill(x, y, w, h, UiColor::rgb(10, 11, 14));
        self.border(
            x,
            y,
            w,
            h,
            if focused {
                pal::BUTTON_BORDER_HOVER
            } else {
                pal::PANEL_BORDER
            },
        );
        let pad = 3;
        let ty = y + (h - 8) / 2;
        if content.is_empty() && !focused {
            self.text(x + pad, ty, 1, pal::TEXT_DIM, placeholder);
        } else {
            let shown = if focused {
                format!("{content}_")
            } else {
                content.to_string()
            };
            let max_chars = ((w - 2 * pad) / 8) as usize;
            let clipped: String = shown.chars().take(max_chars).collect();
            self.text(x + pad, ty, 1, pal::TEXT, &clipped);
        }
        self.region(id, r);
    }

    /// Background gradient shared by menu screens.
    fn menu_background(&mut self) {
        self.fill(0, 0, self.w, self.h / 2, pal::BACKGROUND_TOP);
        self.fill(
            0,
            self.h / 2,
            self.w,
            self.h - self.h / 2,
            pal::BACKGROUND_BOTTOM,
        );
    }

    fn panel(&mut self, x: i32, y: i32, w: i32, h: i32) {
        self.fill(x, y, w, h, pal::PANEL);
        self.border(x, y, w, h, pal::PANEL_BORDER);
    }
}

fn onoff(v: bool) -> &'static str {
    if v {
        "ON"
    } else {
        "OFF"
    }
}

// ---------------------------------------------------------------------------
// Title
// ---------------------------------------------------------------------------

fn title(ctx: &mut Ctx) {
    ctx.menu_background();
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.ctext(cx, 34, 3, pal::TEXT, "MC-SPINE");
    ctx.ctext(
        cx,
        62,
        1,
        pal::TEXT_DIM,
        tr(
            lang,
            "clean-room native client",
            "クリーンルーム ネイティブクライアント",
        ),
    );

    let bw = 200;
    let x = cx - bw / 2;
    let mut y = 92;
    let step = 24;
    ctx.btn(
        WidgetId::TitleSingleplayer,
        lr(x, y, bw, 20),
        tr(lang, "Singleplayer", "シングルプレイ"),
    );
    y += step;
    ctx.btn(
        WidgetId::TitleMultiplayer,
        lr(x, y, bw, 20),
        tr(lang, "Multiplayer", "マルチプレイ"),
    );
    y += step;
    ctx.btn(
        WidgetId::TitleFriends,
        lr(x, y, bw, 20),
        tr(lang, "Play with Friends", "フレンドと遊ぶ"),
    );
    y += step;
    ctx.btn(
        WidgetId::TitleMods,
        lr(x, y, bw, 20),
        tr(lang, "Mods & Packs", "Modとパック"),
    );
    y += step;
    ctx.btn(
        WidgetId::TitleSettings,
        lr(x, y, bw, 20),
        tr(lang, "Settings", "設定"),
    );
    y += step;
    ctx.btn(
        WidgetId::TitleQuit,
        lr(x, y, bw, 20),
        tr(lang, "Quit", "終了"),
    );

    ctx.text(
        4,
        ctx.h - 12,
        1,
        pal::TEXT_DIM,
        "mc-spine client-ui 0.1.0 - zero-dep pure Rust",
    );

    // Quiet optional corner links — rendered only when a URL is set.
    let ly = ctx.h - 20;
    let mut lx = ctx.w - 4;
    if !ctx.state.contribute_url.is_empty() {
        lx -= 76;
        ctx.btn(
            WidgetId::ContributeLink,
            lr(lx, ly, 72, 16),
            tr(lang, "Contribute", "貢献する"),
        );
    }
    if !ctx.state.support_url.is_empty() {
        lx -= 64 + 4;
        ctx.btn(
            WidgetId::SupportLink,
            lr(lx, ly, 64, 16),
            tr(lang, "Support", "支援する"),
        );
    }
}

// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------

fn settings(ctx: &mut Ctx, active: SettingsTab) {
    ctx.menu_background();
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.ctext(cx, 8, 2, pal::TEXT, tr(lang, "Settings", "設定"));

    // Tab strip.
    let tw = 88;
    let gap = 4;
    let total = 5 * tw + 4 * gap;
    let mut tx = cx - total / 2;
    for tab in SettingsTab::ALL {
        let id = match tab {
            SettingsTab::Video => WidgetId::TabVideo,
            SettingsTab::Audio => WidgetId::TabAudio,
            SettingsTab::Qol => WidgetId::TabQol,
            SettingsTab::FairPlay => WidgetId::TabFairPlay,
            SettingsTab::Language => WidgetId::TabLanguage,
        };
        let is_active = tab == active;
        let hot = ctx.hovered(id);
        ctx.fill(
            tx,
            30,
            tw,
            18,
            if is_active {
                pal::BUTTON_HOVER
            } else if hot {
                pal::BUTTON
            } else {
                pal::BUTTON_DISABLED
            },
        );
        ctx.border(tx, 30, tw, 18, pal::BUTTON_BORDER);
        if is_active {
            ctx.fill(tx, 30 + 17, tw, 1, pal::ACCENT);
        }
        let label = tab.label(lang);
        let (lx, ly) = ctx.centered_in(tx + tw / 2, 30, 18, label, 1);
        ctx.text(lx, ly, 1, pal::TEXT, label);
        ctx.region(id, lr(tx, 30, tw, 18));
        tx += tw + gap;
    }

    let y0 = 56;
    match active {
        SettingsTab::Video => video_tab(ctx, y0),
        SettingsTab::Audio => audio_tab(ctx, y0),
        SettingsTab::Qol => qol_tab(ctx, y0),
        SettingsTab::FairPlay => fairplay_tab(ctx, y0),
        SettingsTab::Language => language_tab(ctx, y0),
    }

    let dw = 100;
    ctx.btn(
        WidgetId::SettingsDone,
        lr(cx - dw / 2, ctx.h - 30, dw, 20),
        tr(lang, "Done", "完了"),
    );
}

/// Row geometry for settings pages: a `320`-wide control column.
fn row(ctx: &Ctx, i: i32, y0: i32) -> (i32, i32) {
    (ctx.w / 2 - 160, y0 + i * 24)
}

fn video_tab(ctx: &mut Ctx, y0: i32) {
    let lang = ctx.lang;
    let v = &ctx.state.settings.video;

    let (x, y) = row(ctx, 0, y0);
    ctx.btn(
        WidgetId::VideoPreset,
        lr(x, y, 320, 20),
        &format!("{}: {}", tr(lang, "Preset", "プリセット"), v.preset.label()),
    );

    let (x, y) = row(ctx, 1, y0);
    let frac = (v.view_distance - 6) as f32 / 26.0;
    ctx.slider(
        WidgetId::VideoViewDistance,
        lr(x, y, 320, 20),
        frac,
        &format!(
            "{}: {} {}",
            tr(lang, "View Distance", "描画距離"),
            v.view_distance,
            tr(lang, "chunks", "チャンク")
        ),
    );

    let (x, y) = row(ctx, 2, y0);
    ctx.btn(
        WidgetId::VideoLod,
        lr(x, y, 320, 20),
        &format!("{}: {}", tr(lang, "Distant LOD", "遠景LOD"), v.lod.label()),
    );

    let (x, y) = row(ctx, 3, y0);
    ctx.btn(
        WidgetId::VideoGpuBackend,
        lr(x, y, 320, 20),
        &format!(
            "{}: {}",
            tr(lang, "GPU Backend", "GPUバックエンド"),
            v.gpu_backend.label()
        ),
    );

    // FPS cap: slider + custom numeric field on the same row (no overlap).
    let (x, y) = row(ctx, 4, y0);
    let frac = v.fps_step_index() as f32 / (FPS_CAP_STEPS.len() - 1) as f32;
    ctx.slider(
        WidgetId::VideoFpsSlider,
        lr(x, y, 210, 20),
        frac,
        &format!("{}: {}", tr(lang, "FPS Cap", "FPS上限"), v.fps_cap_label()),
    );
    ctx.textfield(
        WidgetId::VideoFpsField,
        lr(x + 218, y, 102, 20),
        ctx.state.fps_field_text(),
        ctx.state.fps_field_active(),
        tr(lang, "custom fps", "カスタムfps"),
    );
    if ctx.state.fps_field_error() {
        ctx.text(
            x + 218,
            y + 22,
            1,
            pal::DANGER,
            tr(lang, "use 0 or 10-2000", "0 または 10-2000"),
        );
    }

    let (x, y) = row(ctx, 5, y0);
    let bg_label = if v.background_fps == 0 {
        tr(lang, "Off", "オフ").to_string()
    } else {
        format!("{} fps", v.background_fps)
    };
    ctx.btn(
        WidgetId::VideoBackgroundFps,
        lr(x, y, 320, 20),
        &format!(
            "{}: {}",
            tr(lang, "Background FPS", "バックグラウンドFPS"),
            bg_label
        ),
    );

    let (x, y) = row(ctx, 6, y0);
    ctx.btn(
        WidgetId::VideoVsync,
        lr(x, y, 320, 20),
        &format!("VSync: {}", onoff(v.vsync)),
    );

    let (x, y) = row(ctx, 7, y0);
    ctx.btn(
        WidgetId::VideoSmoothLighting,
        lr(x, y, 320, 20),
        &format!(
            "{}: {}",
            tr(lang, "Smooth Lighting", "スムースライティング"),
            onoff(v.smooth_lighting)
        ),
    );
}

fn audio_tab(ctx: &mut Ctx, y0: i32) {
    let lang = ctx.lang;
    let a = &ctx.state.settings.audio;

    let rows: [(WidgetId, &str, u8); 7] = [
        (WidgetId::AudioMaster, "Master Volume", a.master),
        (WidgetId::AudioMusic, "Music", a.music),
        (WidgetId::AudioBlocks, "Blocks", a.blocks),
        (WidgetId::AudioHostile, "Hostile Mobs", a.hostile),
        (WidgetId::AudioFriendly, "Friendly Mobs", a.friendly),
        (
            WidgetId::AudioMaxVolumeCap,
            "Max-Volume Limiter",
            a.max_volume_cap,
        ),
        (
            WidgetId::AudioMaxConcurrent,
            "Same-Sound Coalescing",
            a.max_concurrent_same_sound,
        ),
    ];
    for (i, (id, name, val)) in rows.iter().enumerate() {
        let (x, y) = row(ctx, i as i32, y0);
        let frac = if *id == WidgetId::AudioMaxConcurrent {
            (*val as f32 - 1.0) / 31.0
        } else {
            *val as f32 / 100.0
        };
        let label = if *id == WidgetId::AudioMaxConcurrent {
            format!("{name}: {val}/tick")
        } else {
            format!("{name}: {val}%")
        };
        ctx.slider(*id, lr(x, y, 320, 20), frac, &label);
    }
    ctx.ctext(
        ctx.w / 2,
        y0 + 7 * 24 + 2,
        1,
        pal::TEXT_DIM,
        tr(
            lang,
            "Limiter caps spike loudness; coalescing thins stacked sounds",
            "リミッターは音量スパイクを抑制し、重複音を間引きます",
        ),
    );
}

